INSERT INTO public.saints (id, name, title, feast_day, feast_month, feast_day_num, born, died, patron_of, bio, full_bio, works, quotes, category, image, prayer, virtues, bible_refs, catechism_refs, church_doc_refs) VALUES
($$bernardo$$, $$São Bernardo de Claraval$$, $$Doutor Melífluo$$, $$20 de Agosto$$, 8, 20, $$1090, Fontaine$$, $$1153, Claraval$$, '{"Apicultores"}'::text[], $$Abade cisterciense, grande devoto de Nossa Senhora e pregador das Cruzadas. Reformou a vida monástica.$$, $$Abade cisterciense, grande devoto de Nossa Senhora e pregador das Cruzadas. Reformou a vida monástica.$$, $$[]$$::jsonb, '{"\"De Maria numquam satis — De Maria nunca se diz o bastante.\""}'::text[], $$doctor$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/3/3b/Bernhard_von_Clairvaux_%28Initiale-B%29.jpg/440px-Bernhard_von_Clairvaux_%28Initiale-B%29.jpg$$, NULL, '{"Devoção mariana","Eloquência"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$bartolomeu$$, $$São Bartolomeu$$, $$Apóstolo$$, $$24 de Agosto$$, 8, 24, $$Séc. I, Caná$$, $$Séc. I, Armênia$$, '{"Curtidores","Encadernadores"}'::text[], $$Identificado com Natanael, "israelita sem falsidade". Pregou na Índia e Armênia, onde foi esfolado vivo.$$, $$Identificado com Natanael, "israelita sem falsidade". Pregou na Índia e Armênia, onde foi esfolado vivo.$$, $$[]$$::jsonb, '{"\"De Nazaré pode sair algo bom?\""}'::text[], $$apostle$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/c/c7/Jusepe_de_Ribera_-_Martyrdom_of_Saint_Bartholomew_-_Google_Art_Project.jpg/440px-Jusepe_de_Ribera_-_Martyrdom_of_Saint_Bartholomew_-_Google_Art_Project.jpg$$, NULL, '{"Sinceridade"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$natividade-maria$$, $$Natividade de Nossa Senhora$$, $$O Nascimento de Maria$$, $$8 de Setembro$$, 9, 8, NULL, NULL, '{"Nascituros"}'::text[], $$Festa que celebra o nascimento da Virgem Maria, filha de São Joaquim e Santa Ana.$$, $$Festa que celebra o nascimento da Virgem Maria, filha de São Joaquim e Santa Ana.$$, $$[]$$::jsonb, '{"\"Bendita és tu entre as mulheres.\""}'::text[], $$virgin$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/7/7c/Albrecht_Altdorfer_-_Nativity_of_the_Virgin_-_Google_Art_Project.jpg/440px-Albrecht_Altdorfer_-_Nativity_of_the_Virgin_-_Google_Art_Project.jpg$$, NULL, '{"Pureza","Eleição"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$nome-maria$$, $$Santíssimo Nome de Maria$$, $$Doce Nome de Maria$$, $$12 de Setembro$$, 9, 12, NULL, NULL, '{"Humanidade"}'::text[], $$Festa que celebra o santo nome de Maria, que significa "senhora" ou "estrela do mar".$$, $$Festa que celebra o santo nome de Maria, que significa "senhora" ou "estrela do mar".$$, $$[]$$::jsonb, '{"\"Ao ouvir o nome de Maria, o Céu se alegra e o inferno treme.\""}'::text[], $$virgin$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/4/4d/Sassoferrato_-_Jungfrun_i_b%C3%B6n_-_Google_Art_Project.jpg/440px-Sassoferrato_-_Jungfrun_i_b%C3%B6n_-_Google_Art_Project.jpg$$, NULL, '{"Devoção"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$exaltacao-cruz$$, $$Exaltação da Santa Cruz$$, $$A Cruz Gloriosa$$, $$14 de Setembro$$, 9, 14, NULL, NULL, '{"Penitentes"}'::text[], $$Festa que celebra a descoberta da verdadeira Cruz por Santa Helena e a vitória da Cruz de Cristo.$$, $$Festa que celebra a descoberta da verdadeira Cruz por Santa Helena e a vitória da Cruz de Cristo.$$, $$[]$$::jsonb, '{"\"Nós, porém, pregamos Cristo crucificado.\""}'::text[], $$confessor$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/b/b8/Agnolo_Gaddi_True_Cross.jpg/440px-Agnolo_Gaddi_True_Cross.jpg$$, NULL, '{"Redenção"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb)
