INSERT INTO public.saints (id, name, title, feast_day, feast_month, feast_day_num, born, died, patron_of, bio, full_bio, works, quotes, category, image, prayer, virtues, bible_refs, catechism_refs, church_doc_refs) VALUES
($$nossa-senhora-dores$$, $$Nossa Senhora das Dores$$, $$Mater Dolorosa$$, $$15 de Setembro$$, 9, 15, NULL, NULL, '{"Aflitos"}'::text[], $$Memória das sete dores de Maria: a profecia de Simeão, a fuga ao Egito, a perda de Jesus no Templo, o encontro na Via Crucis, a crucificação, a deposição e a sepultura.$$, $$Memória das sete dores de Maria: a profecia de Simeão, a fuga ao Egito, a perda de Jesus no Templo, o encontro na Via Crucis, a crucificação, a deposição e a sepultura.$$, $$[]$$::jsonb, '{"\"Uma espada traspassará a tua alma.\""}'::text[], $$virgin$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/5/59/Mater_Dolorosa_by_Carlo_Dolci.jpg/440px-Mater_Dolorosa_by_Carlo_Dolci.jpg$$, NULL, '{"Compaixão","Sofrimento"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$mateus$$, $$São Mateus$$, $$Apóstolo e Evangelista$$, $$21 de Setembro$$, 9, 21, $$Séc. I, Cafarnaum$$, $$Séc. I, Etiópia$$, '{"Contadores","Banqueiros"}'::text[], $$Publicano chamado por Jesus, autor do primeiro Evangelho. Pregou na Etiópia.$$, $$Publicano chamado por Jesus, autor do primeiro Evangelho. Pregou na Etiópia.$$, $$[]$$::jsonb, '{"\"Segue-me! E ele se levantou e o seguiu.\""}'::text[], $$apostle$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/4/48/Caravaggio_-_The_Calling_of_Saint_Matthew.jpg/440px-Caravaggio_-_The_Calling_of_Saint_Matthew.jpg$$, NULL, '{"Conversão","Obediência"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$arcanjos$$, $$Santos Arcanjos Miguel, Gabriel e Rafael$$, $$Os Três Arcanjos$$, $$29 de Setembro$$, 9, 29, NULL, NULL, '{"Soldados","Polícia","Médicos"}'::text[], $$Os três arcanjos mencionados na Escritura: Miguel o defensor, Gabriel o mensageiro, Rafael o curador.$$, $$Os três arcanjos mencionados na Escritura: Miguel o defensor, Gabriel o mensageiro, Rafael o curador.$$, $$[]$$::jsonb, '{"\"Quem é como Deus?\""}'::text[], $$confessor$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/b/b3/Guido_Reni_031.jpg/440px-Guido_Reni_031.jpg$$, NULL, '{"Proteção","Mensagem","Cura"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$anjos-guarda$$, $$Santos Anjos da Guarda$$, $$Protetores Celestes$$, $$2 de Outubro$$, 10, 2, NULL, NULL, '{"Crianças","Vigilantes"}'::text[], $$Festa que celebra os anjos designados por Deus para guardar e proteger cada pessoa.$$, $$Festa que celebra os anjos designados por Deus para guardar e proteger cada pessoa.$$, $$[]$$::jsonb, '{"\"Ele enviará seus anjos para te guardar em todos os teus caminhos.\""}'::text[], $$confessor$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/c/c2/Bernardo_Strozzi_-_Guardian_Angel.jpg/440px-Bernardo_Strozzi_-_Guardian_Angel.jpg$$, NULL, '{"Proteção"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$nossa-senhora-rosario$$, $$Nossa Senhora do Rosário$$, $$Rainha do Santo Rosário$$, $$7 de Outubro$$, 10, 7, NULL, NULL, '{"Rosário"}'::text[], $$Festa instituída após a victory de Lepanto em 1571, atribuída à intercessão de Nossa Senhora do Rosário.$$, $$Festa instituída após a victory de Lepanto em 1571, atribuída à intercessão de Nossa Senhora do Rosário.$$, $$[]$$::jsonb, '{"\"Rezai o Rosário todos os dias.\""}'::text[], $$virgin$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/c/c5/Bartolom%C3%A9_Esteban_Murillo_-_Our_Lady_of_the_Rosary_-_Google_Art_Project.jpg/440px-Bartolom%C3%A9_Esteban_Murillo_-_Our_Lady_of_the_Rosary_-_Google_Art_Project.jpg$$, NULL, '{"Oração","Meditação"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb)
