INSERT INTO public.saints (id, name, title, feast_day, feast_month, feast_day_num, born, died, patron_of, bio, full_bio, works, quotes, category, image, prayer, virtues, bible_refs, catechism_refs, church_doc_refs) VALUES
($$santos-inocentes$$, $$Santos Inocentes$$, $$Os Primeiros Mártires$$, $$28 de Dezembro$$, 12, 28, NULL, $$Séc. I, Belém$$, '{"Crianças"}'::text[], $$Os meninos de Belém mortos por ordem de Herodes na tentativa de matar o Menino Jesus. Primeiros mártires do cristianismo.$$, $$Os meninos de Belém mortos por ordem de Herodes na tentativa de matar o Menino Jesus. Primeiros mártires do cristianismo.$$, $$[]$$::jsonb, '{"\"Uma voz se ouviu em Ramá, choro e grande lamento.\""}'::text[], $$martyr$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/e/e5/Guido_Reni_-_Massacre_of_the_Innocents.jpg/440px-Guido_Reni_-_Massacre_of_the_Innocents.jpg$$, NULL, '{"Inocência"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$sagrada-familia$$, $$Sagrada Família$$, $$Jesus, Maria e José$$, $$30 de Dezembro$$, 12, 30, NULL, NULL, '{"Famílias"}'::text[], $$Festa que celebra a família de Nazaré como modelo de fé, amor e santidade para todas as famílias cristãs.$$, $$Festa que celebra a família de Nazaré como modelo de fé, amor e santidade para todas as famílias cristãs.$$, $$[]$$::jsonb, '{"\"E Jesus crescia em sabedoria, estatura e graça diante de Deus e dos homens.\""}'::text[], $$confessor$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/e/e3/Murillo_sagrada_familia_del_pajarito.jpg/440px-Murillo_sagrada_familia_del_pajarito.jpg$$, NULL, '{"Família","Amor"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$sao-severino$$, $$São Severino de Nórica$$, $$Apóstolo dos Bávaros$$, $$8 de Janeiro$$, 1, 8, NULL, NULL, '{}'::text[], $$Monge que evangelizou os povos germânicos durante as invasões bárbaras.$$, $$Monge que evangelizou os povos germânicos durante as invasões bárbaras.$$, $$[]$$::jsonb, '{}'::text[], $$martyr$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/c/c2/Fra_Angelico_052.jpg/440px-Fra_Angelico_052.jpg$$, NULL, '{}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$sao-adriao$$, $$São Adrião de Canterbury$$, $$Abade e Mestre$$, $$9 de Janeiro$$, 1, 9, NULL, NULL, '{}'::text[], $$Abade africano que se tornou grande educador na Inglaterra anglo-saxã.$$, $$Abade africano que se tornou grande educador na Inglaterra anglo-saxã.$$, $$[]$$::jsonb, '{}'::text[], $$confessor$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/f/f4/Fra_Angelico_031.jpg/440px-Fra_Angelico_031.jpg$$, NULL, '{}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$sao-gregorio-nissa$$, $$São Gregório de Nissa$$, $$Padre Capadócio$$, $$10 de Janeiro$$, 1, 10, $$335, Capadócia$$, $$395, Capadócia$$, '{"Teólogos","Místicos"}'::text[], $$Irmão de São Basílio, grande teólogo da doutrina trinitária e um dos pais da mística cristã.$$, $$Irmão de São Basílio, grande teólogo da doutrina trinitária e um dos pais da mística cristã.$$, $$[]$$::jsonb, '{"\"O conceito que temos de Deus não é Deus.\""}'::text[], $$doctor$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/e/e3/St-thomas-aquinas.jpg/440px-St-thomas-aquinas.jpg$$, NULL, '{"Contemplação","Sabedoria"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb)
