INSERT INTO public.saints (id, name, title, feast_day, feast_month, feast_day_num, born, died, patron_of, bio, full_bio, works, quotes, category, image, prayer, virtues, bible_refs, catechism_refs, church_doc_refs) VALUES
($$sao-teodosio$$, $$São Teodósio Cenobiarca$$, $$Pai dos Cenobitas$$, $$11 de Janeiro$$, 1, 11, $$423, Capadócia$$, $$529, Palestina$$, '{"Monges"}'::text[], $$Monge palestino que fundou numerosas comunidades monásticas (cenóbios) na Terra Santa e defendeu a ortodoxia contra o monofisismo.$$, $$Monge palestino que fundou numerosas comunidades monásticas (cenóbios) na Terra Santa e defendeu a ortodoxia contra o monofisismo.$$, $$[]$$::jsonb, '{"\"A vida em comum é a escola da caridade.\""}'::text[], $$confessor$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/f/f4/Fra_Angelico_031.jpg/440px-Fra_Angelico_031.jpg$$, NULL, '{"Comunidade","Fé"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$sao-bento-biscop$$, $$São Bento Biscop$$, $$Abade e Erudito$$, $$12 de Janeiro$$, 1, 12, $$628, Northumbria$$, $$689, Wearmouth$$, '{"Músicos","Pintores"}'::text[], $$Monge inglês que fundou os mosteiros de Wearmouth e Jarrow, trazendo da Itália livros e arte que permitiram o florescimento da cultura cristã na Inglaterra.$$, $$Monge inglês que fundou os mosteiros de Wearmouth e Jarrow, trazendo da Itália livros e arte que permitiram o florescimento da cultura cristã na Inglaterra.$$, $$[]$$::jsonb, '{"\"Os livros são tesouros da alma.\""}'::text[], $$confessor$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/f/f4/Fra_Angelico_031.jpg/440px-Fra_Angelico_031.jpg$$, NULL, '{"Cultura","Zelo"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$sao-felix-nola$$, $$São Félix de Nola$$, $$Confessor e Mártir$$, $$14 de Janeiro$$, 1, 14, NULL, NULL, '{}'::text[], $$Sacerdote italiano que suportou prisões e torturas pela fé.$$, $$Sacerdote italiano que suportou prisões e torturas pela fé.$$, $$[]$$::jsonb, '{}'::text[], $$confessor$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/f/f4/Fra_Angelico_031.jpg/440px-Fra_Angelico_031.jpg$$, NULL, '{}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$sao-paulo-tebas$$, $$São Paulo de Tebas$$, $$Primeiro Eremita$$, $$15 de Janeiro$$, 1, 15, NULL, NULL, '{}'::text[], $$Considerado o primeiro eremita cristão, viveu sozinho no deserto egípcio por 90 anos.$$, $$Considerado o primeiro eremita cristão, viveu sozinho no deserto egípcio por 90 anos.$$, $$[]$$::jsonb, '{}'::text[], $$confessor$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/f/f4/Fra_Angelico_031.jpg/440px-Fra_Angelico_031.jpg$$, NULL, '{}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$sao-marcelo-papa$$, $$São Marcelo I$$, $$Papa Confessor$$, $$16 de Janeiro$$, 1, 16, $$Séc. III, Roma$$, $$309, Roma$$, '{"Roma"}'::text[], $$Papa que reorganizou a Igreja após a perseguição de Diocleciano, exigindo penitência dos que renegaram a fé ("lapsi") antes de reintegrá-los.$$, $$Papa que reorganizou a Igreja após a perseguição de Diocleciano, exigindo penitência dos que renegaram a fé ("lapsi") antes de reintegrá-los.$$, $$[]$$::jsonb, '{"\"A ordem na Igreja exige fidelidade e penitência.\""}'::text[], $$pope$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/2/2d/Cathedra_Petri_adjusted.JPG/440px-Cathedra_Petri_adjusted.JPG$$, NULL, '{"Justiça","Misericórdia"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb)
